using Godot;
using System;
using System.Collections.Generic;
using Settings=Godot.Collections.Dictionary;

public partial class TransformationWorkspaceOperations
{
    public void refresh_tools(Control owner)
    {
        var panel=Item<HBoxContainer>(owner,"tool_context");Clear(panel);var canvas=Item<Control>(owner,"canvas");string tool=canvas.Get("tool").AsString();if(tool is "brush" or "eraser" or "fill" or "shape"){var color=Attach(panel,new ColorPickerButton {Color=canvas.Get("color").AsColor(),CustomMinimumSize=new Vector2(42,28)});color.ColorChanged+=value=>canvas.Set("color",value);}if(tool is "brush" or "eraser"){NumberControl(owner,panel,"Size · Shift+wheel",canvas.Get("brush_size").AsDouble(),1,500,1,value=>canvas.Set("brush_size",value),false,false);NumberControl(owner,panel,"Opacity",canvas.Get("brush_opacity").AsDouble(),0,1,.01,value=>canvas.Set("brush_opacity",value),false,false);Choice(panel,new[]{"Normal","Stroke correct"},canvas.Get("stroke_correct").AsBool()?"Stroke correct":"Normal",value=>canvas.Set("stroke_correct",value=="Stroke correct"));}else if(tool=="fill")NumberControl(owner,panel,"Threshold · Shift+wheel",canvas.Get("fill_threshold").AsDouble(),0,1,.01,value=>canvas.Set("fill_threshold",value),false,false);else if(tool=="shape")Choice(panel,new[]{"Rectangle","Ellipse"},owner.Get("shape_kind").AsString().Capitalize(),value=>owner.Set("shape_kind",value.ToLowerInvariant()));else if(tool=="pixel_select"){string current=canvas.Get("pixel_box_select").AsBool()?"Box (Shift: lasso)":canvas.Get("pixel_mode").AsString().Capitalize();Choice(panel,new[]{"Brush","Erase","Fill","Box (Shift: lasso)"},current,value=>{canvas.Set("pixel_mode",value=="Erase"?"erase":value=="Fill"?"fill":"brush");canvas.Set("pixel_box_select",value.StartsWith("Box",StringComparison.Ordinal));});Action(panel,"Extract selection",()=>owner.Call("extract_selection"),"Move the selected pixels into a new independent component");Action(panel,"Detach at playhead",()=>owner.Call("detach_at_playhead"),"Non-destructive timed split; source drawings stay intact");Action(panel,"Clear",()=>{Session(owner).Call("begin");Session(owner).Set("pixel_mask",default(Variant));Session(owner).Get("pixel_reference").AsGodotDictionary().Clear();Session(owner).Call("commit","Clear pixel selection");});}else{Action(panel,"Fit",()=>canvas.Call("fit"));Caption(panel,"Drag handles · W draw / V move · P pivot");}
    }
    private void ChangeKeys(Control owner,string title,Action<Resource,Resource> operation)
    {
        var session=Session(owner);session.Call("begin");var selected=session.Get("selected_keys").AsGodotArray();foreach(var raw in Document(owner).Get("components").AsGodotArray()){var item=raw.As<Resource>();if(item.Get("locked").AsBool())continue;foreach(var keyRaw in item.Get("keys").AsGodotArray()){var key=keyRaw.As<Resource>();foreach(var id in selected)if(id.AsString()==key.Get("id").AsString()){operation(item,key);break;}}}var errors=Document(owner).Call("validate").AsStringArray();if(errors.Length>0){session.Call("cancel");Item<Label>(owner,"status").Text=errors[0];}else session.Call("commit",title);
    }
    public void refresh_keys(Control owner)
    {
        var panel=Item<HBoxContainer>(owner,"key_fields");Clear(panel);Action(panel,"Events…",()=>owner.Call("events_dialog"));var selection=selected_key(owner);if(selection.Count==0){Caption(panel,"I inserts selected state · Click ruler to scrub · Drag diamonds to move · Ctrl+D duplicate · Delete removes keys");return;}var key=selection["key"].As<Resource>();var item=selection["component"].As<Resource>();if(item.Get("locked").AsBool()){Caption(panel,"Unlock this component to edit its keyframes.");return;}var times=new Dictionary<string,double>();var chosen=Session(owner).Get("selected_keys").AsGodotArray();foreach(var raw in Document(owner).Get("components").AsGodotArray())foreach(var frameRaw in raw.AsGodotObject().Get("keys").AsGodotArray()){var frame=frameRaw.As<Resource>();foreach(var id in chosen)if(id.AsString()==frame.Get("id").AsString()){times[frame.Get("id").AsString()]=frame.Get("time").AsDouble();break;}}
        NumberControl(owner,panel,"Key time (s)",key.Get("time").AsDouble(),0,Document(owner).Get("duration").AsDouble(),.01,value=>{double delta=value-times[key.Get("id").AsString()];foreach(var raw in Document(owner).Get("components").AsGodotArray()){var component=raw.As<Resource>();if(component.Get("locked").AsBool())continue;foreach(var frameRaw in component.Get("keys").AsGodotArray()){var frame=frameRaw.As<Resource>();if(times.TryGetValue(frame.Get("id").AsString(),out var at))frame.Set("time",at+delta);}}});
        var names=new List<string>();foreach(var state in item.Get("states").AsGodotArray())names.Add(state.AsGodotObject().Get("title").AsString());Choice(panel,names,item.Call("state_for_id",key.Get("state_id")).AsGodotObject().Get("title").AsString(),value=>ChangeKeys(owner,"Key state",(component,frame)=>{foreach(var state in component.Get("states").AsGodotArray())if(state.AsGodotObject().Get("title").AsString()==value){frame.Set("state_id",state.AsGodotObject().Get("id"));break;}}));var modes=new[]{"Auto Morph","Shape Morph","Guided Morph","Grow / Reveal","Step","Crossfade"};string mode=key.Get("mode").AsString();string display=System.Array.IndexOf(modes,mode)>=0?mode:mode=="Reveal"?"Grow / Reveal":"Auto Morph";Choice(panel,modes,display,value=>ChangeKeys(owner,"Transition mode",(component,frame)=>frame.Set("mode",value)));Action(panel,"Curve…",()=>owner.Call("curve_dialog"));Action(panel,"Match points…",()=>owner.Call("match_dialog"));Action(panel,"Morph…",()=>owner.Call("morph_options"));
        NumberControl(owner,panel,"Extra turns",key.Get("turns").AsDouble(),-20,20,1,value=>{foreach(var raw in Document(owner).Get("components").AsGodotArray()){var component=raw.As<Resource>();if(component.Get("locked").AsBool())continue;foreach(var frameRaw in component.Get("keys").AsGodotArray()){var frame=frameRaw.As<Resource>();foreach(var id in chosen)if(id.AsString()==frame.Get("id").AsString()){frame.Set("turns",(long)Math.Round(value,MidpointRounding.AwayFromZero));break;}}}});Action(panel,"Reveal path",()=>{edit_key_state(owner);owner.Call("set_tool","reveal_path");},"Click points in the canvas to define the selected transition's reveal path");Action(panel,"Clear path",()=>ChangeKeys(owner,"Clear reveal path",(component,frame)=>frame.Set("reveal_path",System.Array.Empty<Vector2>())));NumberControl(owner,panel,"Reveal width",key.Get("reveal_width").AsDouble(),.01,2,.01,value=>key.Set("reveal_width",value));Action(panel,"⌫",()=>Session(owner).Call("delete_keys"),"Delete selected keyframes");
    }
}
